<?php require 'cek_akses.php'; require 'koneksi.php'; /* ========================= CEK ROLE ADMIN ========================= */ $role = $_SESSION['role'] ?? ''; $name = $_SESSION['name'] ?? 'User'; if ($role !== 'admin') { http_response_code(403); exit('Akses ditolak. Halaman ini khusus Admin.'); } /* ========================= FUNGSI OUTPUT AMAN ========================= */ function e($value) { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES, 'UTF-8'); } /* ========================= TAMBAH GURU ========================= */ if (isset($_POST['tambah'])) { $nip = trim($_POST['nip'] ?? ''); $nama = trim($_POST['nama'] ?? ''); $email = trim($_POST['email'] ?? ''); $status_aktif = isset($_POST['status_aktif']) ? (int)$_POST['status_aktif'] : 1; $user_id = trim($_POST['user_id'] ?? ''); if ($nip === '' || $nama === '' || $email === '') { echo "<script>alert('NIP, nama, dan email wajib diisi!');location.href='menu2.php';</script>"; exit; } if (!filter_var($email, FILTER_VALIDATE_EMAIL)) { echo "<script>alert('Format email tidak valid!');location.href='menu2.php';</script>"; exit; } try { $stmt = $pdo->prepare(" INSERT INTO t_guru (nip, nama, email, status_aktif, user_id) VALUES (:nip, :nama, :email, :status_aktif, :user_id) "); $stmt->execute([ ':nip' => $nip, ':nama' => $nama, ':email' => $email, ':status_aktif' => $status_aktif, ':user_id' => $user_id === '' ? null : (int)$user_id ]); echo "<script>alert('Data guru berhasil ditambahkan!');location.href='menu2.php';</script>"; exit; } catch (PDOException $ex) { error_log($ex->getMessage()); echo "<script>alert('Gagal menambahkan guru. Pastikan NIP, email, dan user ID sesuai database.');location.href='menu2.php';</script>"; exit; } } /* ========================= EDIT GURU ========================= */ if (isset($_POST['edit'])) { $id = (int)($_POST['id'] ?? 0); $nip = trim($_POST['nip'] ?? ''); $nama = trim($_POST['nama'] ?? ''); $email = trim($_POST['email'] ?? ''); $status_aktif = (int)($_POST['status_aktif'] ?? 0); $user_id = trim($_POST['user_id'] ?? ''); if ($id <= 0 || $nip === '' || $nama === '' || $email === '') { echo "<script>alert('Lengkapi data guru dengan benar!');location.href='menu2.php';</script>"; exit; } if (!filter_var($email, FILTER_VALIDATE_EMAIL)) { echo "<script>alert('Format email tidak valid!');location.href='menu2.php';</script>"; exit; } try { $stmt = $pdo->prepare(" UPDATE t_guru SET nip = :nip, nama = :nama, email = :email, status_aktif = :status_aktif, user_id = :user_id WHERE id = :id "); $stmt->execute([ ':nip' => $nip, ':nama' => $nama, ':email' => $email, ':status_aktif' => $status_aktif, ':user_id' => $user_id === '' ? null : (int)$user_id, ':id' => $id ]); echo "<script>alert('Data guru berhasil diperbarui!');location.href='menu2.php';</script>"; exit; } catch (PDOException $ex) { error_log($ex->getMessage()); echo "<script>alert('Gagal memperbarui data guru. Periksa data yang dimasukkan.');location.href='menu2.php';</script>"; exit; } } /* ========================= HAPUS GURU ========================= */ if (isset($_POST['hapus'])) { $id = (int)($_POST['id'] ?? 0); if ($id <= 0) { header('Location: menu2.php'); exit; } try { $stmt = $pdo->prepare("DELETE FROM t_guru WHERE id = :id"); $stmt->execute([':id' => $id]); echo "<script>alert('Data guru berhasil dihapus!');location.href='menu2.php';</script>"; exit; } catch (PDOException $ex) { error_log($ex->getMessage()); echo "<script>alert('Guru tidak dapat dihapus karena masih digunakan oleh data lain.');location.href='menu2.php';</script>"; exit; } } /* ========================= DATA GURU UNTUK EDIT ========================= */ $data_edit = null; if (isset($_GET['edit'])) { $id_edit = (int)$_GET['edit']; $stmt = $pdo->prepare("SELECT * FROM t_guru WHERE id = :id"); $stmt->execute([':id' => $id_edit]); $data_edit = $stmt->fetch(PDO::FETCH_ASSOC); if (!$data_edit) { echo "<script>alert('Data guru tidak ditemukan!');location.href='menu2.php';</script>"; exit; } } /* ========================= PENCARIAN GURU ========================= */ $cari = trim($_GET['cari'] ?? ''); if ($cari !== '') { $stmt = $pdo->prepare(" SELECT * FROM t_guru WHERE nip LIKE :cari OR nama LIKE :cari OR email LIKE :cari ORDER BY id DESC "); $stmt->execute([':cari' => "%{$cari}%"]); } else { $stmt = $pdo->query("SELECT * FROM t_guru ORDER BY id DESC"); } $data_guru = $stmt->fetchAll(PDO::FETCH_ASSOC); $total_guru = count($data_guru); /* ========================= STATISTIK GURU ========================= */ $total_aktif = (int)$pdo->query(" SELECT COUNT(*) FROM t_guru WHERE status_aktif = 1 ")->fetchColumn(); $total_nonaktif = (int)$pdo->query(" SELECT COUNT(*) FROM t_guru WHERE status_aktif = 0 ")->fetchColumn(); /* ========================= MENU SIDEBAR ========================= */ $menus = [ ['Dashboard', 'dashboard.php', '⌂'], ['Kelola Siswa', 'menu1.php', '♙'], ['Kelola Guru', 'menu2.php', '♧'], ['Jenis Pelanggaran', 'menu3.php', '▤'], ['Admin', 'menu4.php', '⚙'], ['Kelola Kelas', 'kelola_kelas.php', '▦'], ['Tahun Ajaran', 'kelola_tahun_ajaran.php', '▣'], ['Penempatan Siswa', 'penempatan_siwa.php', '⇄'], ['Wali Kelas', 'kelola_wali_kelas.php', '♧'], ['Kategori Pelanggaran', 'kelola_kategori_pelanggaran.php', '▤'], ['Laporan', 'laporan.php', '▧'] ]; ?> <!DOCTYPE html> <html lang="id"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Kelola Guru | UKK 2026</title> <style> *{box-sizing:border-box} body{margin:0;font-family:"Segoe UI",Arial,sans-serif;background:#f1f5f9;color:#1e293b} a{text-decoration:none} .sidebar{position:fixed;top:0;left:0;bottom:0;width:250px;background:#0f172a;color:white;padding:24px 15px;overflow-y:auto;z-index:100} .brand{padding:0 12px 24px;border-bottom:1px solid #334155;margin-bottom:20px} .brand h2{margin:0 0 6px;font-size:23px;letter-spacing:1px} .brand p{margin:0;font-size:12px;color:#94a3b8} .user-info{background:#1e293b;border-radius:12px;padding:13px;margin-bottom:20px} .user-info strong{display:block;overflow-wrap:anywhere;font-size:14px} .user-info span{display:inline-block;margin-top:7px;padding:4px 9px;border-radius:20px;background:#2563eb;font-size:11px;text-transform:uppercase} .nav-title{margin:18px 12px 9px;font-size:10px;color:#64748b;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase} .nav-link{display:flex;align-items:center;gap:12px;padding:12px;margin:4px 0;color:#cbd5e1;font-size:13px;border-radius:9px;transition:.2s} .nav-link:hover{background:#1e293b;color:white} .nav-link.active{background:#2563eb;color:white;font-weight:600} .nav-icon{width:20px;text-align:center;font-size:17px} .logout{display:block;padding:12px;margin-top:22px;color:#fecaca;border:1px solid #7f1d1d;border-radius:9px;text-align:center;font-size:13px} .logout:hover{background:#7f1d1d;color:white} .main{margin-left:250px;padding:28px;min-height:100vh} .topbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px} .topbar h1{margin:0;font-size:27px;color:#0f172a} .breadcrumb{margin-top:7px;color:#64748b;font-size:13px} .welcome{color:#475569;font-size:13px;text-align:right} .welcome strong{color:#0f172a} .card{background:white;border-radius:14px;padding:22px;margin-bottom:22px;box-shadow:0 3px 12px rgba(15,23,42,.04);border:1px solid #e2e8f0} .stats-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:22px} .stat-card{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:20px;display:flex;justify-content:space-between;align-items:center;gap:10px} .stat-card p{margin:0 0 8px;font-size:13px;color:#64748b} .stat-card h2{margin:0;font-size:28px;color:#0f172a} .stat-icon{width:45px;height:45px;display:grid;place-items:center;background:#dbeafe;color:#2563eb;border-radius:12px;font-size:22px} .section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px} .section-heading h2{margin:0;font-size:18px} .section-heading p{margin:6px 0 0;color:#64748b;font-size:12px} .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px} .form-group label{display:block;margin-bottom:7px;font-size:13px;font-weight:600;color:#334155} .form-group input,.form-group select,.search-input{width:100%;padding:11px 12px;border:1px solid #cbd5e1;border-radius:8px;background:white;font:inherit;font-size:13px;outline:none} .form-group input:focus,.form-group select:focus,.search-input:focus{border-color:#2563eb;box-shadow:0 0 0 3px #dbeafe} .full-width{grid-column:1/-1} .form-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px;margin-top:18px} .btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;padding:10px 13px;cursor:pointer;font:inherit;font-size:12px;font-weight:600;transition:.2s} .btn-primary{background:#2563eb;color:white} .btn-primary:hover{background:#1d4ed8} .btn-secondary{background:#e2e8f0;color:#334155} .btn-edit{background:#fef3c7;color:#92400e} .btn-delete{background:#fee2e2;color:#b91c1c} .search-form{display:flex;gap:9px;width:100%;max-width:520px} .search-input{flex:1;min-width:0} .table-wrap{width:100%;overflow-x:auto} table{width:100%;min-width:850px;border-collapse:collapse;font-size:12px} thead{background:#f8fafc} th{padding:13px 12px;text-align:left;color:#475569;border-bottom:1px solid #e2e8f0;white-space:nowrap} td{padding:12px;border-bottom:1px solid #f1f5f9;color:#334155;vertical-align:middle} tbody tr:hover{background:#f8fafc} .status{display:inline-block;padding:5px 9px;border-radius:20px;font-size:11px;font-weight:600} .status.aktif{background:#dcfce7;color:#166534} .status.nonaktif{background:#fee2e2;color:#991b1b} .empty{padding:30px;text-align:center;color:#64748b} .table-footer{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:16px;color:#64748b;font-size:12px} .action-group{display:flex;gap:6px;align-items:center} .inline-form{display:inline} @media(max-width:1000px){.sidebar{width:210px}.main{margin-left:210px;padding:20px}.stats-grid{grid-template-columns:1fr}} @media(max-width:650px){.sidebar{position:relative;width:100%;max-height:none;bottom:auto}.main{margin-left:0;padding:15px}.topbar{align-items:flex-start;flex-direction:column}.welcome{text-align:left}.form-grid{grid-template-columns:1fr}.full-width{grid-column:auto}.search-form{max-width:100%;flex-wrap:wrap}.search-input{flex-basis:100%}.card{padding:16px}} </style> </head> <body> <aside class="sidebar"> <div class="brand"> <h2>UKK 2026</h2> <p>Sistem Pelanggaran Siswa</p> </div> <div class="user-info"> <strong><?= e($name) ?></strong> <span><?= e($role) ?></span> </div> <div class="nav-title">Menu Utama</div> <?php foreach ($menus as $menu): ?> <a class="nav-link <?= $menu[1] === 'menu2.php' ? 'active' : '' ?>" href="<?= e($menu[1]) ?>"> <span class="nav-icon"><?= e($menu[2]) ?></span> <span><?= e($menu[0]) ?></span> </a> <?php endforeach; ?> <a class="logout" href="logout.php" onclick="return confirm('Yakin ingin keluar dari aplikasi?')"> ⇥ &nbsp; Logout </a> </aside> <main class="main"> <header class="topbar"> <div> <h1>Kelola Guru</h1> <div class="breadcrumb">Dashboard / Kelola Guru</div> </div> <div class="welcome"> Selamat datang,<br> <strong><?= e($name) ?></strong> (<?= e($role) ?>) </div> </header> <div class="stats-grid"> <div class="stat-card"> <div> <p>Total Guru</p> <h2><?= $total_guru ?></h2> </div> <div class="stat-icon">♧</div> </div> <div class="stat-card"> <div> <p>Guru Aktif</p> <h2><?= $total_aktif ?></h2> </div> <div class="stat-icon">✓</div> </div> <div class="stat-card"> <div> <p>Guru Nonaktif</p> <h2><?= $total_nonaktif ?></h2> </div> <div class="stat-icon">−</div> </div> </div> <section class="card"> <div class="section-heading"> <div> <h2><?= $data_edit ? 'Edit Data Guru' : 'Tambah Data Guru' ?></h2> <p>Masukkan informasi guru pada formulir berikut.</p> </div> </div> <form method="POST" action="menu2.php"> <?php if ($data_edit): ?> <input type="hidden" name="id" value="<?= e($data_edit['id']) ?>"> <?php endif; ?> <div class="form-grid"> <div class="form-group"> <label for="nip">NIP *</label> <input type="text" id="nip" name="nip" required placeholder="Masukkan NIP guru" value="<?= e($data_edit['nip'] ?? '') ?>"> </div> <div class="form-group"> <label for="nama">Nama Guru *</label> <input type="text" id="nama" name="nama" required placeholder="Masukkan nama guru" value="<?= e($data_edit['nama'] ?? '') ?>"> </div> <div class="form-group"> <label for="email">Email *</label> <input type="email" id="email" name="email" required placeholder="nama@email.com" value="<?= e($data_edit['email'] ?? '') ?>"> </div> <div class="form-group"> <label for="user_id">User ID (opsional)</label> <input type="number" id="user_id" name="user_id" min="1" placeholder="Contoh: 1" value="<?= e($data_edit['user_id'] ?? '') ?>"> </div> <div class="form-group full-width"> <label for="status_aktif">Status Guru</label> <select id="status_aktif" name="status_aktif"> <option value="1" <?= (string)($data_edit['status_aktif'] ?? '1') === '1' ? 'selected' : '' ?>> Aktif </option> <option value="0" <?= (string)($data_edit['status_aktif'] ?? '1') === '0' ? 'selected' : '' ?>> Nonaktif </option> </select> </div> </div> <div class="form-actions"> <?php if ($data_edit): ?> <button type="submit" name="edit" class="btn btn-primary"> Simpan Perubahan </button> <a href="menu2.php" class="btn btn-secondary">Batal</a> <?php else: ?> <button type="submit" name="tambah" class="btn btn-primary"> + Tambah Guru </button> <button type="reset" class="btn btn-secondary">Reset Form</button> <?php endif; ?> </div> </form> </section> <section class="card"> <div class="section-heading"> <div> <h2>Data Guru</h2> <p>Daftar guru yang tersimpan di dalam sistem.</p> </div> </div> <form method="GET" action="menu2.php" class="search-form"> <input class="search-input" type="text" name="cari" placeholder="Cari NIP, nama, atau email..." value="<?= e($cari) ?>"> <button type="submit" class="btn btn-primary">Cari</button> <a href="menu2.php" class="btn btn-secondary">Reset</a> </form> <br> <div class="table-wrap"> <table> <thead> <tr> <th>No.</th> <th>ID</th> <th>NIP</th> <th>Nama Guru</th> <th>Email</th> <th>Status</th> <th>User ID</th> <th>Aksi</th> </tr> </thead> <tbody> <?php if ($total_guru > 0): ?> <?php $no = 1; ?> <?php foreach ($data_guru as $guru): ?> <tr> <td><?= $no++ ?></td> <td><?= e($guru['id']) ?></td> <td><?= e($guru['nip']) ?></td> <td><strong><?= e($guru['nama']) ?></strong></td> <td><?= e($guru['email']) ?></td> <td> <?php if ((int)$guru['status_aktif'] === 1): ?> <span class="status aktif">Aktif</span> <?php else: ?> <span class="status nonaktif">Nonaktif</span> <?php endif; ?> </td> <td><?= e($guru['user_id']) ?></td> <td> <div class="action-group"> <a class="btn btn-edit" href="menu2.php?edit=<?= (int)$guru['id'] ?>"> Edit </a> <form method="POST" action="menu2.php" class="inline-form" onsubmit="return confirm('Yakin ingin menghapus guru ini?')"> <input type="hidden" name="id" value="<?= (int)$guru['id'] ?>"> <button type="submit" name="hapus" class="btn btn-delete"> Hapus </button> </form> </div> </td> </tr> <?php endforeach; ?> <?php else: ?> <tr> <td colspan="8" class="empty"> <?php if ($cari !== ''): ?> Data guru dengan kata kunci "<?= e($cari) ?>" tidak ditemukan. <?php else: ?> Belum ada data guru. <?php endif; ?> </td> </tr> <?php endif; ?> </tbody> </table> </div> <div class="table-footer"> <span>Jumlah data ditampilkan: <strong><?= $total_guru ?></strong></span> <span>UKK 2026 — Sistem Pelanggaran Siswa</span> </div> </section> </main> </body> </html>